--@note -------------- 晕染特效 卡拉OK模板 --------------

--@note 修改「配置」那一行 code once 里的参数后，在 自动化 菜单执行「应用卡拉OK模板」，会删掉旧的 fx 行并按歌词行重新生成。执行前要先在系统里装好 SPED 用的两款字体，Aegisub 按系统字体计算字宽。原歌词行保留为 karaoke 注释行，文字和标签没有改动。

--@code once | 环境
--[[ 模板环境里只有 string/math/_G，这里把要用的全局函数引进来 ]] tonumber, tostring, ipairs, pairs, type, table, unicode, aegisub = _G.tonumber, _G.tostring, _G.ipairs, _G.pairs, _G.type, _G.table, _G.unicode, _G.aegisub wc = {}

--@code once | 配置
--[[ 时间单位 ms，透明度 00 为不透明，FF 为全透明 ]] --[[ spread 墨色从起点铺到句子两端的最长时间，front 每条切片从透明到不透明所用的时间 ]] --[[ lead 墨色比颜料晚出现的时间，wet 颜料提前出现的时间，waver 显现速度的随机起伏，strip 切片宽度 px ]] --[[ grid 水彩网格的格距 px，levels 水彩各层的浓度阈值（由浅到深），edge_levels 硬边积色两层的阈值 ]] --[[ reach 颜料从笔画中线渗到边缘的时间，stages 渗开分几步，soft 渗开前沿的过渡时间 ]] --[[ wash_wet 和 wash_dry 是每层水彩刚渗开和干后的透明度，dry_ms 变干所用的时间 ]] --[[ edge_alpha 硬边积色的透明度，wet_peak 字形颜料最浓时的透明度 ]] --[[ out_ms 退场化开的时间，out_jit 各字退场的随机先后 ]] --[[ grain_min 颜料浓度低于它的地方不加颗粒，mottle_alpha 和 mottle_light 是深色、浅色斑驳的透明度 ]] --[[ blob_cell 软颗粒的格距 px，blob_dark 和 blob_light 控制深色、浅色软颗粒的多少，blob_alpha 和 blob_alpha_light 是它们的透明度 ]] --[[ grain_cell 细颗粒的格距 px，grain_dark 控制细颗粒的多少，grain_alpha 和 grain_blur 是它的透明度和模糊 ]] --[[ paper 是纸面的颜色（RGB），用于浅色斑驳和浅色软颗粒；场景表最后一项颗粒强度按比例调整这些透明度 ]] wc.cfg = { spread = 560, front = 300, lead = 60, wet = 240, waver = 45, strip = 6, grid = 5, levels = {0.06, 0.3, 0.54, 0.78}, edge_levels = {0.6, 0.85}, reach = 650, stages = 7, soft = 260, wash_wet = 0xC4, wash_dry = 0xD6, dry_ms = 900, edge_alpha = 0xD4, wet_peak = 0x50, out_ms = 440, out_jit = 130, grain_min = 0.12, mottle_alpha = 0xE8, mottle_light = 0xE2, blob_cell = 5, blob_dark = 0.55, blob_light = 0.45, blob_alpha = 0xDA, blob_alpha_light = 0xD4, grain_cell = 3.5, grain_dark = 0.25, grain_alpha = 0xC8, grain_blur = 0.45, paper = "FAF6EB", } --[[ 每个画面的水彩颜色，依次是开始时间、结束时间、深色、中间色、浅色（RGB），取自 ED 画面，最后一项是颗粒强度 ]] wc.scenes = { {1329000, 1334950, "A0585C", "C98C8A", "E8C4BE", 1}, {1334950, 1339650, "A2B23A", "C6D262", "E2EAA4", 0.9}, {1339650, 1356000, "B5806F", "D8A897", "EED3C6", 0.8}, {1356000, 1366050, "927A8B", "BCA6B2", "DED0D7", 0.9}, {1366050, 1375900, "C2653A", "DA9866", "EFC8A2", 0.7}, {1375900, 1384050, "5DBA48", "9CDF85", "D0F3C2", 0.8}, {1384050, 1394900, "5AAFD0", "95D0E4", "CCEDF4", 0.4}, {1394900, 1404400, "A2B23A", "C6D262", "E2EAA4", 0.9}, {1404400, 1412000, "C66E5C", "E0A18E", "F2D1C5", 1}, }

--@code once | 工具函数
function wc.clamp(x, a, b) if x < a then return a elseif x > b then return b end return x end function wc.num(x, p) local s = string.format(p, x):gsub("0+$", ""):gsub("%.$", "") if s == "-0" then s = "0" end return s end function wc.f(x) return wc.num(x, "%.2f") end --[[ 逐字坐标要精确到 1/128 px，才能和 libass 排整句时的取整一致 ]] function wc.p(x) return wc.num(x, "%.7f") end --[[ 和 libass 的 lrint 一样，恰好是 .5 时取偶数 ]] function wc.lrint(x) local f = math.floor(x) local r = x - f if r > 0.5 then return f + 1 elseif r < 0.5 then return f end if f % 2 == 0 then return f end return f + 1 end function wc.hash(a, b, c) local x = math.sin(a * 12.9898 + b * 78.233 + (c or 0) * 37.719) * 43758.5453 return x - math.floor(x) end function wc.rgb(h) return tonumber(h:sub(1, 2), 16), tonumber(h:sub(3, 4), 16), tonumber(h:sub(5, 6), 16) end function wc.c(h) local r, g, b = wc.rgb(h) return string.format("&H%02X%02X%02X&", b, g, r) end function wc.mix(h1, h2, t) local r1, g1, b1 = wc.rgb(h1) local r2, g2, b2 = wc.rgb(h2) local function m(x, y) return math.floor(x + (y - x) * t + 0.5) end return string.format("%02X%02X%02X", m(r1, r2), m(g1, g2), m(b1, b2)) end function wc.a(v) return string.format("&H%02X&", wc.clamp(math.floor(v + 0.5), 0, 255)) end function wc.srgb(sc) local b, g, r = sc:match("&H%x%x(%x%x)(%x%x)(%x%x)") return r .. g .. b end function wc.ms(t) return math.floor(t / 10 + 0.5) * 10 end function wc.scene(t) for _, s in ipairs(wc.scenes) do if t >= s[1] and t < s[2] then return s end end return wc.scenes[1] end --[[ 读一个标签块里的 \alpha \1a \3a，返回更新后的填充和描边透明度 ]] function wc.alphas(tags, a1, a3) for name, val in tags:gmatch("\\(%d?%a+)([^\\}]*)") do if name:sub(1, 5) == "alpha" then val = name:sub(6) .. val name = "alpha" elseif name:match("^[1-4]a") then val = name:sub(3) .. val name = name:sub(1, 2) end local v = val:match("^&?H?(%x%x?)") v = v and tonumber(v, 16) if v then if name == "alpha" then a1, a3 = v, v elseif name == "1a" then a1 = v elseif name == "3a" then a3 = v end end end return a1, a3 end --[[ 按透明度状态分段重建整句文字，fn 给出每段开头的标签 ]] function wc.runs(g, fn) local out, key = "", nil for _, ch in ipairs(g.chars) do local k = ch.a1 .. "," .. ch.a3 if k ~= key then out = out .. "{" .. fn(ch) .. "}" key = k end out = out .. ch.c end return out end --[[ 永远不会开始的 \t。没有 \pos 的行加上它，libass 就不会为了防重叠把它挪到别处，画面本身不变 ]] wc.still = "\\t(99999999,99999999,\\1a&HFF&)"

--@code once | 版面解析
--[[ 按原行的 \an \pos 或边距算出每个字的位置，并记录每个字的透明度状态 ]] function wc.geom(L) local st, t = L.styleref, L.text local an = tonumber(t:match("\\an(%d)")) if not an then local a = tonumber(t:match("\\a(%d+)")) if a then an = ({[1] = 1, [2] = 2, [3] = 3, [5] = 7, [6] = 8, [7] = 9, [9] = 4, [10] = 5, [11] = 6})[a] end end an = an or st.align local h, vc = an % 3, an <= 3 and 0 or (an <= 6 and 1 or 2) local px, py = t:match("\\pos%(%s*([%-%d%.]+)%s*,%s*([%-%d%.]+)%s*%)") px, py = tonumber(px), tonumber(py) local ml = L.margin_l > 0 and L.margin_l or st.margin_l local mr = L.margin_r > 0 and L.margin_r or st.margin_r local mv = L.margin_t > 0 and L.margin_t or st.margin_t local first = t:match("^%b{}") or "{}" local g = {an = an, vc = vc, fs = st.fontsize * st.scale_y / 100} g.base = first:sub(2, -2):gsub("\\fade?%b()", "") g.rest = t:sub(#(t:match("^%b{}") or "") + 1) local fin, fout = first:match("\\fade?%(%s*(%d+)%s*,%s*(%d+)%s*%)") g.fin, g.fout = tonumber(fin) or 300, tonumber(fout) or 300 local a1 = tonumber(st.color1:match("&H(%x%x)"), 16) local a3 = tonumber(st.color3:match("&H(%x%x)"), 16) local chars, pen = {}, 0 for blk, tags in ("{}" .. t .. "{}"):gmatch("([^{]*)(%b{})") do for c in unicode.chars(blk) do local w = math.floor(aegisub.text_extents(st, c) * 64 + 0.5) chars[#chars + 1] = {c = c, pen = pen, wd = w, a1 = a1, a3 = a3, hide = a1 >= 255, sp = (c == " " or c == "　")} pen = pen + w end a1, a3 = wc.alphas(tags, a1, a3) end local W = pen local function gx(p) if px then if h == 1 then return wc.lrint(px * 64 + p) end if h == 2 then return wc.lrint(px * 64 - W / 2 + p) end return wc.lrint(px * 64 - W + p) end local maxw = (meta.res_x - mr) - ml local shift = h == 1 and 0 or (h == 2 and (maxw - W / 64) / 2 or (maxw - W / 64)) return wc.lrint(ml * 64 + p + wc.lrint(shift * 64)) end for _, ch in ipairs(chars) do ch.x = gx(ch.pen) / 64 ch.w = ch.wd / 64 ch.cx = ch.x + ch.w / 2 end if not py then if vc == 0 then py = meta.res_y - mv elseif vc == 1 then py = meta.res_y / 2 else py = mv end end g.py = py g.cyc = vc == 0 and py - g.fs / 2 or (vc == 1 and py or py + g.fs / 2) g.lan = ({1, 4, 7})[vc + 1] g.chars = chars return g end

--@code once | 噪声
--[[ 平滑的值噪声和多层叠加的分形噪声，取值 0 到 1，决定水彩的形状、深浅和渗开的快慢 ]] function wc.vnoise(x, y, s) local xi, yi = math.floor(x), math.floor(y) local xf, yf = x - xi, y - yi local u, v = xf * xf * (3 - 2 * xf), yf * yf * (3 - 2 * yf) local a, b = wc.hash(xi, yi, s), wc.hash(xi + 1, yi, s) local c, d = wc.hash(xi, yi + 1, s), wc.hash(xi + 1, yi + 1, s) local top = a + (b - a) * u return top + (c + (d - c) * u - top) * v end function wc.fbm(x, y, s, oct) local sum, amp, f, norm = 0, 1, 1, 0 for o = 1, oct or 4 do sum = sum + amp * wc.vnoise(x * f, y * f, s + o * 1.7) norm = norm + amp amp, f = amp * 0.45, f * 2.03 end return sum / norm end

--@code once | 等值线
--[[ 闭合折线的点数精简（Douglas-Peucker），tol 是允许的偏差 px ]] function wc.simplify(p, tol) local n = #p local q = {} for k = 1, n do q[k] = p[k] end q[n + 1] = p[1] local far, fd = 1, -1 for k = 2, n do local dx, dy = q[k][1] - q[1][1], q[k][2] - q[1][2] if dx * dx + dy * dy > fd then far, fd = k, dx * dx + dy * dy end end local keep, stack, t2 = {[1] = true, [far] = true}, {{1, far}, {far, n + 1}}, tol * tol while #stack > 0 do local seg = table.remove(stack) local a, b = seg[1], seg[2] if b - a > 1 then local ax, ay = q[a][1], q[a][2] local dx, dy = q[b][1] - ax, q[b][2] - ay local L2 = dx * dx + dy * dy local best, bd = nil, t2 for k = a + 1, b - 1 do local px, py = q[k][1] - ax, q[k][2] - ay local d if L2 == 0 then d = px * px + py * py else local c = px * dy - py * dx d = c * c / L2 end if d > bd then best, bd = k, d end end if best then keep[best] = true stack[#stack + 1] = {a, best} stack[#stack + 1] = {best, b} end end end local r = {} for k = 1, n do if keep[k] then r[#r + 1] = q[k] end end return r end --[[ 从网格上提取 f > t 的区域轮廓（marching squares），返回 ASS 绘图指令，坐标单位 1/4 px，配合 \p3 使用 ]] --[[ f 存放 (nx+1)*(ny+1) 个格点的值，格点间距 cs px。网格最外一圈的值要低于 t，轮廓才会闭合 ]] --[[ 每段轮廓都让区域内部保持在行进方向的同一侧，外轮廓和洞的方向相反，libass 按非零环绕规则填充时洞是空的 ]] function wc.contour(f, nx, ny, cs, t) local W = nx + 1 local pts, nxt, order = {}, {}, {} local function point(id) if pts[id] then return end local base = math.floor(id / 2) local i = base % W local j = (base - i) / W local a = f[base] local b = id % 2 == 1 and f[base + W] or f[base + 1] local u = (t - a) / (b - a) if id % 2 == 1 then pts[id] = {i * cs, (j + u) * cs} else pts[id] = {(i + u) * cs, j * cs} end end for j = 0, ny - 1 do for i = 0, nx - 1 do local n0 = j * W + i local v0, v1, v2, v3 = f[n0], f[n0 + 1], f[n0 + W + 1], f[n0 + W] local c0, c1, c2, c3 = v0 > t, v1 > t, v2 > t, v3 > t if not (c0 == c1 and c1 == c2 and c2 == c3) then --[[ 沿格子四边顺时针走一圈，记下每个交点是走进区域还是走出区域 ]] local cr = {} if c0 ~= c1 then cr[#cr + 1] = {n0 * 2, c1} end if c1 ~= c2 then cr[#cr + 1] = {(n0 + 1) * 2 + 1, c2} end if c2 ~= c3 then cr[#cr + 1] = {(n0 + W) * 2, c3} end if c3 ~= c0 then cr[#cr + 1] = {n0 * 2 + 1, c0} end local n = #cr local mid = (v0 + v1 + v2 + v3) / 4 > t for k = 1, n do if cr[k][2] then local m = (n == 2 or not mid) and k % n + 1 or (k - 2) % n + 1 local e1, e2 = cr[k][1], cr[m][1] point(e1) point(e2) nxt[e1] = e2 order[#order + 1] = e1 end end end end end local out, used = {}, {} for _, e in ipairs(order) do if not used[e] then local loop, cur = {}, e while cur and not used[cur] do used[cur] = true loop[#loop + 1] = pts[cur] cur = nxt[cur] end if #loop >= 6 then loop = wc.simplify(loop, 0.35) local s = {} for k, p in ipairs(loop) do s[k] = math.floor(p[1] * 4 + 0.5) .. " " .. math.floor(p[2] * 4 + 0.5) end out[#out + 1] = "m " .. s[1] .. " l " .. table.concat(s, " ", 2) end end end return table.concat(out, " ") end

--@code once | 水彩
--[[ 每句背后一笔横向的水彩。先在句子周围的网格上算出颜料浓度，再按几个浓度阈值提取轮廓，叠成由浅到深的几层 ]] --[[ 浓度在边缘下降的快慢随位置变化：降得快的地方边缘清楚，颜料积在边上颜色更深；降得慢的地方边缘晕开 ]] --[[ 颜料从墨色起点附近开始渗开，先湿后干，干后出现颗粒，一直留到这句结束，最后和字一起淡出 ]] function wc.wash(x) local C, g, sc, fs = wc.cfg, x.g, x.sc, x.g.fs local deep, mid, light = sc[3], sc[4], sc[5] local pf, F, A, CC = string.format, wc.f, wc.a, wc.c local cs = C.grid local ns = {} for k = 1, 8 do ns[k] = (x.seed * (1.37 + 0.71 * k) + 11 * k) % 97 end local ca, cb = x.x0 - fs * 0.15, x.x1 + fs * 0.15 local el = fs * (0.55 + 0.6 * wc.hash(x.seed, 31, 1)) local er = fs * (0.55 + 0.6 * wc.hash(x.seed, 32, 2)) local rx0 = math.floor((ca - el - fs * 0.45) / cs) * cs local rx1 = math.ceil((cb + er + fs * 0.45) / cs) * cs local ry0 = math.floor((g.cyc - fs * 1.4) / cs) * cs local ry1 = math.ceil((g.cyc + fs * 1.4) / cs) * cs local nx, ny = (rx1 - rx0) / cs, (ry1 - ry0) / cs local W = nx + 1 local reach = math.min(C.reach, x.D * 0.22) local P, E, Ar = {}, {}, {} local amin, amax = math.huge, -math.huge for j = 0, ny do local py = ry0 + j * cs for i = 0, nx do local px = rx0 + i * cs local q = j * W + i local p, e, a = 0, 0, 1e9 if i > 0 and j > 0 and i < nx and j < ny then local yc = g.cyc + fs * 0.24 * (wc.fbm(px / (fs * 2.4), 0.5, ns[1], 2) - 0.5) local hw = fs * (0.48 + 0.45 * wc.fbm(px / (fs * 1.7), 1.5, ns[2], 2)) local dxn = math.max(0, ca - px) / el + math.max(0, px - cb) / er local dyn = (py - yc) / hw local D = 1 - math.sqrt(dxn * dxn + dyn * dyn) + (wc.fbm(px / (fs * 0.75), py / (fs * 0.55), ns[3], 3) - 0.5) * 0.5 + (wc.fbm(px / (fs * 0.28), py / (fs * 0.24), ns[4], 2) - 0.5) * 0.16 local hard = wc.clamp((wc.fbm(px / (fs * 1.1), py / (fs * 0.9), ns[5], 2) - 0.5) / 0.18, 0, 1) * wc.clamp(1 - dxn * 1.5, 0, 1) p = wc.clamp(D / (0.5 - 0.38 * hard), 0, 1) * (0.62 + 0.55 * wc.fbm(px / (fs * 1.2), py / (fs * 0.9), ns[6], 2)) e = hard * wc.clamp(D / 0.02, 0, 1) * wc.clamp(1 - D / 0.13, 0, 1) a = x.delay(px) * 0.85 - 200 + reach * wc.clamp(1 - D, 0, 1.4) * (0.6 + 0.8 * wc.fbm(px / (fs * 0.6), py / (fs * 0.5), ns[7], 2)) if p > C.levels[1] then if a < amin then amin = a end if a > amax then amax = a end end end P[q], E[q], Ar[q] = p, e, a end end if amax < amin then return end local S, tau = C.stages, C.soft local t0 = math.max(0, amin) local t1 = math.max(t0 + S * 40, amax + tau) local dt = (t1 - t0) / S local dry = math.min(C.dry_ms, x.D * 0.3) local bw, bd = fs * 0.1, fs * 0.035 local head = pf("\\an7\\pos(%d,%d)\\p3\\shad0\\bord0", rx0, ry0) local function event(s, e, tags, shape) x.add(0, s, e, "{" .. head .. tags .. "}" .. shape .. "{\\p0}") end local function outro(s, b) if x.tout <= 0 then return "" end return pf("\\t(%d,%d,\\1a&HFF&\\blur%s)", x.X0 - 40 - s, x.D - s, F(b + fs * 0.18)) end local nl = #C.levels for li, lv in ipairs(C.levels) do local u = (li - 1) / math.max(1, nl - 1) local col = li < nl and CC(wc.mix(light, mid, 0.2 + 0.8 * u)) or CC(wc.mix(mid, deep, 0.35)) for st = 1, S do local ts = t0 + dt * st local f = {} for q = 0, W * (ny + 1) - 1 do f[q] = P[q] * wc.clamp((ts - Ar[q]) / tau, 0, 1) end local shape = wc.contour(f, nx, ny, cs, lv) if shape ~= "" then local s = ts - dt if st < S then event(s, ts + dt, pf("\\blur%s\\1c%s\\1a&HFF&\\t(0,%d,\\1a%s)\\t(%d,%d,\\1a&HFF&)", F(bw), col, dt, A(C.wash_wet), dt, 2 * dt), shape) else event(s, x.D, pf("\\blur%s\\1c%s\\1a&HFF&\\t(0,%d,\\1a%s)\\t(%d,%d,\\1a%s\\blur%s)%s", F(bw), col, dt, A(C.wash_wet), dt, dt + dry, A(C.wash_dry), F(bd), outro(s, bd)), shape) end end end end local ecol = CC(wc.mix(deep, mid, 0.3)) for _, lv in ipairs(C.edge_levels) do local shape = wc.contour(E, nx, ny, cs, lv) if shape ~= "" then local s = t1 - dt event(s, x.D, pf("\\blur%s\\1c%s\\1a&HFF&\\t(0,%d,\\1a%s)%s", F(fs * 0.025), ecol, dt + dry, A(C.edge_alpha), outro(s, fs * 0.025)), shape) end end wc.grain(x, {P = P, E = E, rx0 = rx0, ry0 = ry0, rx1 = rx1, ry1 = ry1, cs = cs, W = W, nx = nx, ny = ny, t1 = t1, dt = dt, dry = dry}) end

--@code once | 颗粒
--[[ 水彩干后的纸面肌理，在水彩变干时淡入，退场时比水彩先淡出。深色部分是颜料在纸纹里沉积，浅色部分是纸面露出来 ]] --[[ 分三层：约 15 像素的斑驳（等值线小岛），3 到 8 像素的软颗粒（模糊的小三角形，互相叠成连续的起伏），1 到 2 像素的细颗粒 ]] --[[ 三层的多少都跟着颜料浓度走，浓的地方明显，水彩边缘淡的地方几乎没有 ]] function wc.grain(x, w) local C, sc, fs = wc.cfg, x.sc, x.g.fs local pf, F, A, CC = string.format, wc.f, wc.a, wc.c local strength = sc[6] or 1 if strength <= 0 then return end local function sample(T, px, py) local fx, fy = (px - w.rx0) / w.cs, (py - w.ry0) / w.cs local i, j = math.floor(fx), math.floor(fy) if i < 0 or j < 0 or i >= w.nx or j >= w.ny then return 0 end local u, v = fx - i, fy - j local q = j * w.W + i local a, b, c, d = T[q], T[q + 1], T[q + w.W], T[q + w.W + 1] return (a + (b - a) * u) * (1 - v) + (c + (d - c) * u) * v end local ms1, ms2, ms3 = x.seed * 7.3 % 89, x.seed * 9.1 % 83, x.seed * 4.7 % 79 local s = w.t1 - w.dt local fade = x.tout > 0 and pf("\\t(%d,%d,\\1a&HFF&)", x.X0 - 40 - s, x.X0 - 40 - s + x.tout * 0.6) or "" local dcol, lcol = CC(wc.mix(sc[3], sc[4], 0.35)), CC(C.paper) local function put(p, shape, col, alpha, blur) if shape == "" then return end x.add(0, s, x.D, pf("{\\an7\\pos(%d,%d)\\p%d\\shad0\\bord0\\blur%s\\1c%s\\1a&HFF&\\t(0,%d,\\1a%s)%s}%s{\\p0}", w.rx0, w.ry0, p, F(blur), col, w.dt + w.dry, A(255 - (255 - alpha) * math.min(1, strength)), fade, shape)) end --[[ 斑驳：在水彩网格上取噪声的高处和低处，各提取一层等值线 ]] local Md, Ml = {}, {} for j = 0, w.ny do local py = w.ry0 + j * w.cs for i = 0, w.nx do local px = w.rx0 + i * w.cs local q = j * w.W + i local p = math.min(w.P[q], 1) local k = wc.clamp(p / 0.25, 0, 1) local n = wc.fbm(px / (fs * 0.3), py / (fs * 0.26), ms3, 3) Md[q] = (n - 0.6 + 0.22 * p) * k Ml[q] = (0.4 - n + 0.22 * p) * k end end put(3, wc.contour(Md, w.nx, w.ny, w.cs, 0), dcol, C.mottle_alpha, fs * 0.04) put(3, wc.contour(Ml, w.nx, w.ny, w.cs, 0), lcol, C.mottle_light, fs * 0.04) --[[ 以 (cx, cy) 为中心、半径约 r 的小三角形，坐标单位 1/2 px（\p2） ]] local function speck(list, cx, cy, r, k) local a0 = wc.hash(cx, cy, k) * 6.2832 local t = {} for m = 0, 2 do local a = a0 + m * 2.0944 + (wc.hash(cx, cy, k + m + 1) - 0.5) * 0.8 local rr = r * (0.7 + 0.6 * wc.hash(cy, cx, k + m + 7)) t[m + 1] = math.floor((cx - w.rx0 + rr * math.cos(a)) * 2 + 0.5) .. " " .. math.floor((cy - w.ry0 + rr * math.sin(a)) * 2 + 0.5) end list[#list + 1] = "m " .. t[1] .. " l " .. t[2] .. " " .. t[3] end local function scatter(cell, salt, fn) for gy = w.ry0 + cell, w.ry1 - cell, cell do for gx = w.rx0 + cell, w.rx1 - cell, cell do local cx = gx + (wc.hash(gx, gy, salt) - 0.5) * cell local cy = gy + (wc.hash(gy, gx, salt + 1) - 0.5) * cell local p = sample(w.P, cx, cy) if p > C.grain_min then fn(cx, cy, math.min(p, 1), wc.hash(gx + x.seed, gy, salt + 2), wc.hash(gx, gy, salt + 3)) end end end end --[[ 软颗粒：深浅两种，按另一层噪声分开聚集 ]] local bd, bl = {}, {} scatter(C.blob_cell, 81, function(cx, cy, p, h, h2) local n = wc.fbm(cx / (fs * 0.16), cy / (fs * 0.14), ms2, 2) if h < p * (0.15 + 1.1 * n) * C.blob_dark then speck(bd, cx, cy, 1.8 + 1.8 * h2, 90) elseif h > 1 - p * (1.15 - n) * C.blob_light then speck(bl, cx, cy, 1.8 + 1.8 * h2, 95) end end) put(2, table.concat(bd, " "), dcol, C.blob_alpha, fs * 0.019) put(2, table.concat(bl, " "), lcol, C.blob_alpha_light, fs * 0.019) --[[ 细颗粒：成片聚集，硬边处更多 ]] local fd = {} scatter(C.grain_cell, 51, function(cx, cy, p, h, h2) local cl = wc.clamp((wc.fbm(cx / (fs * 0.22), cy / (fs * 0.2), ms1, 2) - 0.4) / 0.3, 0, 1) if h < (p * cl + 0.8 * sample(w.E, cx, cy)) * C.grain_dark then speck(fd, cx, cy, 0.6 + 0.6 * h2, 60) end end) put(2, table.concat(fd, " "), CC(wc.mix(sc[3], sc[4], 0.15)), C.grain_alpha, C.grain_blur) x.grains = (x.grains or 0) + #bd + #bl + #fd end

--@code once | 字形颜料
--[[ 墨色出现之前，每个字先以画面色的颜料出现，随后被墨色盖住 ]] function wc.bleed(x) local C, g, sc, fs = wc.cfg, x.g, x.sc, x.g.fs local pf, F, A, CC = string.format, wc.f, wc.a, wc.c for _, i in ipairs(x.vis) do local ch = g.chars[i] local di = x.delay(ch.cx) local lpos = pf("\\an%d\\pos(%s,%s)", g.lan, wc.p(ch.x), wc.p(g.py)) x.add(1, di - C.wet, di + C.lead + 560, pf("{%s\\shad0\\bord0\\blur%s\\1c%s\\1a&HFF&\\t(0,%d,\\1a%s)\\t(%d,%d,\\blur%s\\1a&HFF&)}%s", lpos, F(fs * 0.07), CC(sc[3]), C.wet * 0.7, A(C.wet_peak), C.wet + C.lead, C.wet + C.lead + 560, F(fs * 0.12), ch.c)) end end

--@code once | 墨色显现
--[[ 整句按竖条切开，墨色从起点向两侧逐条显现。每条用的都是整句原文，所以和原行逐像素一致 ]] function wc.front(x) local C, g = wc.cfg, x.g local pf, A = string.format, wc.a local sw = C.strip local n = math.max(1, math.ceil((x.x1 - x.x0 + 24) / sw)) local sx0 = x.x0 - 12 local strips, full = {}, 0 for k = 0, n - 1 do local a = math.floor(sx0 + k * sw + 0.5) local b = math.floor(sx0 + (k + 1) * sw + 0.5) local t1 = wc.ms(x.delay((a + b) / 2) + C.lead) strips[#strips + 1] = {k == 0 and a - 80 or a, k == n - 1 and b + 80 or b, t1} full = math.max(full, t1 + x.tf) end x.full = wc.ms(full + 5) if x.X0 < x.full then x.X0 = x.full end local body = wc.runs(g, function(ch) if ch.hide then return "\\alpha&HFF&" end return pf("\\1a&HFF&\\3a&HFF&\\t(0,%d,0.75,\\1a%s\\3a%s)", x.tf, A(ch.a1), A(ch.a3)) end) for _, s in ipairs(strips) do x.add(3, s[3], math.min(x.full, x.X0), pf("{%s%s\\clip(%d,0,%d,%d)}%s", g.base, wc.still, s[1], s[2], meta.res_y, body)) end end

--@code once | 退场
--[[ 每个字在自己的时刻化开：光晕先淡出，字略微放大、变模糊、变淡 ]] --[[ 字开始化开之前，仍然显示整句里的它（按字切片），保证和静止时完全一致 ]] function wc.leave(x) local C, g, sc, fs = wc.cfg, x.g, x.sc, x.g.fs local light, ink = sc[5], x.ink local pf, F, A, CC = string.format, wc.f, wc.a, wc.c local vis = x.vis local function slot(m) local ch = g.chars[vis[m]] local a = (m == 1) and ch.x - 100 or (g.chars[vis[m - 1]].x + g.chars[vis[m - 1]].w + ch.x) / 2 local b = (m == #vis) and ch.x + ch.w + 100 or (ch.x + ch.w + g.chars[vis[m + 1]].x) / 2 return math.floor(a + 0.5), math.floor(b + 0.5) end for m, i in ipairs(vis) do local ch = g.chars[i] local ca, cb = slot(m) local clip = pf("\\clip(%d,0,%d,%d)", ca, cb, meta.res_y) local xr = x.xo[i] - x.X0 local glow = wc.runs(g, function(c) if c.hide then return "\\alpha&HFF&" end return pf("\\1a&HFF&\\3a%s\\t(%d,%d,\\3a&HFF&)", A(c.a3), xr, xr + x.tout * 0.7) end) x.add(3, x.X0, x.D, pf("{%s%s%s}%s", g.base, wc.still, clip, glow)) x.add(4, x.X0, x.xo[i], pf("{%s\\bord0\\blur0%s%s}%s", g.base, wc.still, clip, wc.runs(g, function(c) return c.hide and "\\alpha&HFF&" or "\\1a" .. A(c.a1) end))) x.add(4, x.xo[i], x.D, pf("{\\an5\\pos(%s,%s)\\shad0\\bord0\\blur0\\1a%s\\t(0,%d,1.2,\\blur%s\\1a&HFF&\\1c%s\\fscx107\\fscy107)}%s", wc.p(ch.cx), wc.p(g.cyc), A(ch.a1), x.tout, F(fs * 0.16), CC(wc.mix(ink, light, 0.6)), ch.c)) end end

--@code once | 生成
--[[ 一句歌词分三段，入场时水彩渗开、字形颜料和墨色依次出现，中间显示原行和干后的水彩，结尾字迹和水彩一起化开消失 ]] function wc.build(L) local C, g = wc.cfg, wc.geom(L) local x = {g = g, sc = wc.scene(L.start_time), D = L.end_time - L.start_time, items = {}} x.ink = wc.srgb(L.styleref.color1) x.seed = L.start_time / 1000 + (g.vc == 0 and 0.37 or 0.71) function x.add(layer, s, e, text) s, e = wc.ms(math.max(0, s)), wc.ms(e) if e > s then x.items[#x.items + 1] = {layer, s, e, text} end end x.vis = {} for i, ch in ipairs(g.chars) do if not ch.hide and not ch.sp then x.vis[#x.vis + 1] = i end end if #x.vis == 0 then return x.items end local first, last = g.chars[x.vis[1]], g.chars[x.vis[#x.vis]] x.x0, x.x1 = first.x, last.x + last.w local S = math.min(C.spread, 200 + 34 * #x.vis, x.D * 0.17) x.tf = math.min(C.front, x.D * 0.12) x.tout = g.fout > 0 and math.min(C.out_ms, x.D * 0.18) or 0 local u0 = 0.14 + 0.3 * wc.hash(x.seed, 1, 1) local ph1, ph2 = wc.hash(x.seed, 2, 2) * 6.2832, wc.hash(x.seed, 3, 3) * 6.2832 function x.delay(px) local u = wc.clamp((px - x.x0) / math.max(1, x.x1 - x.x0), 0, 1) local base = S * (math.abs(u - u0) / math.max(u0, 1 - u0)) ^ 0.85 return math.max(0, base + C.waver * (math.sin(u * 7.3 + ph1) * 0.6 + math.sin(u * 17.9 + ph2) * 0.4)) end x.xo, x.X0 = {}, x.D for _, i in ipairs(x.vis) do x.xo[i] = x.tout > 0 and wc.ms(x.D - x.tout - C.out_jit * wc.hash(x.seed, i, 9)) or x.D x.X0 = math.min(x.X0, x.xo[i]) end wc.front(x) for _, i in ipairs(x.vis) do x.xo[i] = math.max(x.xo[i], x.X0) end wc.wash(x) wc.bleed(x) if x.X0 > x.full then x.add(4, x.full, x.X0, "{" .. g.base .. wc.still .. "}" .. g.rest) end if x.tout > 0 then wc.leave(x) end return x.items end

--@code once | 输出
--[[ template line 每循环一次输出一行特效 ]] function wc.emit() if syl.i ~= 1 then return "" end if j == 1 then wc.items = wc.build(orgline) maxloop(math.max(1, #wc.items)) end local it = wc.items[j] if not it then line.comment = true return "" end relayer(it[1]) retime("set", orgline.start_time + it[2], orgline.start_time + it[3]) return it[4] end

--@template line notext
!wc.emit()!

--@template line notext style=SPED中
!wc.emit()!

